text:
5 一个简单例子
两位裁缝各自报告版型和客人差多少。裁缝 B 报的差距更小，可 B 做的是一位身材更标准、两个版型都合身的客人。要比较版型，就把两个版型分别套在两位客人身上，这就是论文的 2×2 交叉（A 为等权模型，B 为市值加权模型）。套在 A 的客人身上，两个版型差不多合身（117.37 对 116.67 个基点）；套在 B 的客人身上，连 A 的版型也只差 75.02 个基点（表 1，第 13 页）。这里，版型是模型的因子，客人是预期收益估计，不合身的程度是阿尔法。真正的客人谁也看不见：两位“客人”都是对不可观测的预期收益的估计，所以交叉比较只说明变的是哪一样，不说明哪份估计更对，判断这一点要靠之后的收益。

试一试。 模型 A 的估计里有一种个股偏离，它的因子无法生成；两个滑块改变的是模型 B。示例默认处于“情形 1”：先点“重置”，再依次点两个情形，留意右上和左下两格。


palette = ({
  naipca_iab: "#18557f", complete: "#18557f",
  qz_ipca: "#8a6a1a",
  ipca: "#6f9cc0", rp_pca: "#7a7a7a", ff5: "#b3b3b3",
  naipca_beta_only: "#8a8378", beta_only: "#8a8378",
  band: "rgba(0,0,0,0.06)", muted: "rgba(0,0,0,0.6)", rule: "rgba(0,0,0,0.1)"
})
LANG = (document.documentElement.lang || "en").startsWith("zh") ? "zh" : "en"
STR = ({ en: { view: "View", cost: "Cost (bp per traded dollar)", universe: "Universe", sample: "Sample (months)", log: "Log scale", models: "Models", statistic: "Statistic", theme: "Theme", sort: "Sort by", method: "Method", scenario: "Scenario", block: "Block (months)", metric: "Metric", intervals: "Intervals", cost_bp: "One-way cost (bp)", failed: "Interactive data failed to load. The static figure is shown instead." },
        zh: { view: "视图", cost: "成本（每交易一美元，基点）", universe: "股票池", sample: "样本（月）", log: "对数坐标", models: "模型", statistic: "统计量", theme: "主题", sort: "排序", method: "方法", scenario: "情景", block: "块长（月）", metric: "指标", intervals: "区间", cost_bp: "单边成本（基点）", failed: "交互数据加载失败，改为显示静态图。" } })
t = (k) =&gt; STR[LANG][k] ?? STR.en[k] ?? k
fmt2 = (x) =&gt; (x == null || Number.isNaN(x)) ? "n/a" : x.toFixed(2)
fmt1 = (x) =&gt; (x == null || Number.isNaN(x)) ? "n/a" : x.toFixed(1)
fmtBp = (x) =&gt; (x == null || Number.isNaN(x)) ? "&gt; 500" : `${Math.round(x)} bp`
parseMonth = (s) =&gt; new Date(`${s}-01T00:00:00Z`)
// Sharpe, annualised, sample std (ddof = 1): matches the release convention
sharpe = (r) =&gt; {
  const n = r.length, m = r.reduce((a, b) =&gt; a + b, 0) / n
  const v = r.reduce((a, b) =&gt; a + (b - m) ** 2, 0) / (n - 1)
  const vol = Math.sqrt(v) * Math.sqrt(12)
  return vol &gt; 1e-12 ? (m * 12) / vol : NaN
}
netSeries = (r, to, bp) =&gt; r.map((x, i) =&gt; x - to[i] * bp / 1e4)
wealthPath = (r) =&gt; { let w = 1; return r.map((x) =&gt; (w *= 1 + x)) }
nberMarks = (nber) =&gt; Plot.rectX(nber, { x1: (d) =&gt; parseMonth(d.start), x2: (d) =&gt; parseMonth(d.end), fill: palette.band })























































































图 1：两个模型，两个阿尔法。五只股票、一个因子的示意数字；表格让每个模型的估计分别面对每个模型的因子。


// Preset stories (set both sliders at once). Story 1 is the default slider state.
pe_toy_presets = {
  const zh = LANG === "zh"
  const presets = [
    [zh ? "情形 1：B 换了估计" : "Story 1: B changed its estimate", 0.5, 0],
    [zh ? "情形 2：B 改进了因子" : "Story 2: B improved its factor", 1, 1],
    [zh ? "重置：两模型相同" : "Reset: identical models", 1, 0]
  ]
  const set = (input, x) =&gt; { input.value = x; input.dispatchEvent(new Event("input", { bubbles: true })) }
  const wrap = html`&lt;div role="group" aria-label="${zh ? "预设情形" : "Preset stories"}" style="display:flex;flex-wrap:wrap;gap:.4rem;margin:0 0 .6rem"&gt;&lt;/div&gt;`
  for (const [label, keep, tilt] of presets) {
    const b = html`&lt;button type="button" class="btn btn-sm btn-outline-secondary"&gt;${label}&lt;/button&gt;`
    b.onclick = () =&gt; { set(viewof pe_toy_keep, keep); set(viewof pe_toy_tilt, tilt) }
    wrap.append(b)
  }
  return wrap
}







viewof pe_toy_keep = Inputs.range([0, 1], { value: 0.5, step: 0.05, label: LANG === "zh" ? "B 的估计：保留 A 偏离的比例" : "B's estimate: share of A's tilt kept" })







viewof pe_toy_tilt = Inputs.range([0, 1], { value: 0, step: 0.05, label: LANG === "zh" ? "B 的因子：向该偏离倾斜的程度" : "B's factor: bend toward that tilt" })







pe_toy_stocks = [1, 2, 3, 4, 5]
pe_toy_stockName = (i) =&gt; LANG === "zh" ? `股票 ${i}` : `Stock ${i}`
pe_toy_betaA = [0.6, 0.9, 1.0, 1.2, 1.5]
pe_toy_premium = 0.5
pe_toy_extra = [0.40, -0.20, 0.10, -0.30, 0.25]
// At tilt = 1, B's exposures tilt fully toward A's stock-specific tilt, so one factor spans A's estimate
pe_toy_shift = pe_toy_extra.map((e) =&gt; 2 * e)
pe_toy_betaB = pe_toy_betaA.map((b, i) =&gt; b + pe_toy_tilt * pe_toy_shift[i])
pe_toy_meanA = pe_toy_betaA.map((b, i) =&gt; b * pe_toy_premium + pe_toy_extra[i])
pe_toy_meanB = pe_toy_betaA.map((b, i) =&gt; b * pe_toy_premium + pe_toy_keep * pe_toy_extra[i])
// Equal-stock projection of an estimate onto the span of one exposure vector
pe_toy_split = (beta, mean) =&gt; {
  const bb = beta.reduce((s, b) =&gt; s + b * b, 0), bm = beta.reduce((s, b, i) =&gt; s + b * mean[i], 0)
  const factor = beta.map((b) =&gt; b * bm / bb)
  return { factor, intercept: mean.map((m, i) =&gt; m - factor[i]) }
}
pe_toy_rms = (r) =&gt; 100 * Math.sqrt(r.reduce((s, x) =&gt; s + x * x, 0) / r.length)   // percent -&gt; basis points
pe_toy_cell = (beta, mean) =&gt; pe_toy_rms(pe_toy_split(beta, mean).intercept)
pe_toy_AA = pe_toy_cell(pe_toy_betaA, pe_toy_meanA)
pe_toy_BB = pe_toy_cell(pe_toy_betaB, pe_toy_meanB)
pe_toy_BA = pe_toy_cell(pe_toy_betaB, pe_toy_meanA)
pe_toy_AB = pe_toy_cell(pe_toy_betaA, pe_toy_meanB)
pe_toy_mA = LANG === "zh" ? "模型 A" : "Model A"
pe_toy_mB = LANG === "zh" ? "模型 B" : "Model B"
pe_toy_pF = LANG === "zh" ? "因子部分" : "Factor part"
pe_toy_pI = LANG === "zh" ? "阿尔法成分" : "Alpha component"
pe_toy_rows = [[pe_toy_mA, pe_toy_betaA, pe_toy_meanA], [pe_toy_mB, pe_toy_betaB, pe_toy_meanB]].flatMap(([m, beta, mean]) =&gt; {
  const s = pe_toy_split(beta, mean)
  return pe_toy_stocks.flatMap((st, i) =&gt; [
    { model: m, stock: st, part: pe_toy_pF, value: s.factor[i] },
    { model: m, stock: st, part: pe_toy_pI, value: s.intercept[i] }
  ])
})
pe_toy_totals = [[pe_toy_mA, pe_toy_meanA], [pe_toy_mB, pe_toy_meanB]].flatMap(([m, mean]) =&gt; pe_toy_stocks.map((st, i) =&gt; ({ model: m, stock: st, value: mean[i] })))




























































































































































pe_toy_chart = Plot.plot({
  width: Math.min(width, 760), height: 280, marginLeft: 50, marginTop: 36, marginBottom: 40, style: { fontFamily: "inherit", fontSize: 12 },
  ariaLabel: LANG === "zh" ? "示意图：预期收益估计拆成因子部分与阿尔法成分" : "Illustrative example: expected-return estimates split into a factor part and an alpha component",
  ariaDescription: LANG === "zh" ? "两个模型下五只示意股票的堆叠柱状图；圆点标出每只股票的预期收益估计合计。" : "Stacked bars for five illustrative stocks under two models. Dots mark each stock's total expected-return estimate.",
  fx: { label: null },
  x: { label: LANG === "zh" ? "股票" : "Stock", axis: "bottom" },
  y: { label: LANG === "zh" ? "预期收益估计（每月 %）" : "Expected-return estimate (% per month)", grid: true },
  color: { domain: [pe_toy_pF, pe_toy_pI], range: [palette.complete, palette.qz_ipca], legend: true },
  marks: [
    Plot.ruleY([0], { stroke: palette.muted }),
    Plot.barY(pe_toy_rows, { fx: "model", x: "stock", y: "value", fill: "part", title: (d) =&gt; `${d.model}, ${pe_toy_stockName(d.stock)}\n${d.part}: ${d.value.toFixed(2)}%` }),
    Plot.dot(pe_toy_totals, { fx: "model", x: "stock", y: "value", fill: "white", stroke: "black", r: 3.5, title: (d) =&gt; `${d.model}, ${pe_toy_stockName(d.stock)}\n${LANG === "zh" ? "预期收益估计合计" : "Total estimate"}: ${d.value.toFixed(2)}%` })
  ]
})







pe_toy_table = {
  const zh = LANG === "zh"
  const u = zh ? " 基点" : " bp"
  const c = (x, diag) =&gt; `&lt;td style="text-align:right;${diag ? "font-weight:600" : ""}"&gt;${fmt1(x)}${u}&lt;/td&gt;`
  return html`&lt;table class="table table-sm" style="max-width:520px"&gt;
  &lt;thead&gt;&lt;tr&gt;&lt;th&gt;${zh ? "因子 ↓ ／ 估计 →" : "Factor ↓ / estimate →"}&lt;/th&gt;&lt;th style="text-align:right"&gt;${zh ? "模型 A 的估计" : "Model A's estimate"}&lt;/th&gt;&lt;th style="text-align:right"&gt;${zh ? "模型 B 的估计" : "Model B's estimate"}&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
  &lt;tbody&gt;&lt;tr&gt;&lt;td&gt;${zh ? "模型 A 的因子" : "Model A's factor"}&lt;/td&gt;${c(pe_toy_AA, true)}${c(pe_toy_AB, false)}&lt;/tr&gt;
  &lt;tr&gt;&lt;td&gt;${zh ? "模型 B 的因子" : "Model B's factor"}&lt;/td&gt;${c(pe_toy_BA, false)}${c(pe_toy_BB, true)}&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;
  &lt;p class="figcaption" style="margin-top:.3rem"&gt;${zh
    ? `各自的阿尔法：A 为 ${fmt1(pe_toy_AA)} 基点，B 为 ${fmt1(pe_toy_BB)} 基点。只换因子（估计固定为 A 的）：${fmt1(pe_toy_AA)} → ${fmt1(pe_toy_BA)} 基点；只换估计（因子固定为 A 的）：${fmt1(pe_toy_AA)} → ${fmt1(pe_toy_AB)} 基点。示意数字，并非论文数据。`
    : `Own alphas: ${fmt1(pe_toy_AA)} bp for A, ${fmt1(pe_toy_BB)} bp for B. Change only the factor (A's estimate held fixed): ${fmt1(pe_toy_AA)} → ${fmt1(pe_toy_BA)} bp. Change only the estimate (A's factor held fixed): ${fmt1(pe_toy_AA)} → ${fmt1(pe_toy_AB)} bp. Illustrative numbers, not the paper's data.`}&lt;/p&gt;`
}







怎么读。每根柱子是一只股票的预期收益估计，拆成因子部分（蓝色）和阿尔法成分（金色），圆点为合计。表格（每月基点）中，加粗的格子是各模型自己的阿尔法。来源：示意数字，并非论文数据；版式参照论文表 1。



留意。 与“重置”相比，两种情形下 B 自己的阿尔法（右下格）都变小了。情形 1 中右上格下降，说明 B 的估计本身更容易被解释；情形 2 中左下格下降，说明 B 的因子更能解释 A 的估计。只有交叉组合能告诉你是哪一种情形。论文的实际数据更像情形 1（表 1，第 13 页）。再拖动滑块：B 的因子倾斜程度等于其估计保留的偏离时，B 自己的阿尔法降为零，越过后又回升。示例只有一个因子、五只等权股票，B 的估计只是按比例缩小 A 的偏离；论文中估计的变化还涉及方向（第 14 页）。

5 一个简单例子

palette = ({
  naipca_iab: "#18557f", complete: "#18557f",
  qz_ipca: "#8a6a1a",
  ipca: "#6f9cc0", rp_pca: "#7a7a7a", ff5: "#b3b3b3",
  naipca_beta_only: "#8a8378", beta_only: "#8a8378",
  band: "rgba(0,0,0,0.06)", muted: "rgba(0,0,0,0.6)", rule: "rgba(0,0,0,0.1)"
})
LANG = (document.documentElement.lang || "en").startsWith("zh") ? "zh" : "en"
STR = ({ en: { view: "View", cost: "Cost (bp per traded dollar)", universe: "Universe", sample: "Sample (months)", log: "Log scale", models: "Models", statistic: "Statistic", theme: "Theme", sort: "Sort by", method: "Method", scenario: "Scenario", block: "Block (months)", metric: "Metric", intervals: "Intervals", cost_bp: "One-way cost (bp)", failed: "Interactive data failed to load. The static figure is shown instead." },
        zh: { view: "视图", cost: "成本（每交易一美元，基点）", universe: "股票池", sample: "样本（月）", log: "对数坐标", models: "模型", statistic: "统计量", theme: "主题", sort: "排序", method: "方法", scenario: "情景", block: "块长（月）", metric: "指标", intervals: "区间", cost_bp: "单边成本（基点）", failed: "交互数据加载失败，改为显示静态图。" } })
t = (k) =&gt; STR[LANG][k] ?? STR.en[k] ?? k
fmt2 = (x) =&gt; (x == null || Number.isNaN(x)) ? "n/a" : x.toFixed(2)
fmt1 = (x) =&gt; (x == null || Number.isNaN(x)) ? "n/a" : x.toFixed(1)
fmtBp = (x) =&gt; (x == null || Number.isNaN(x)) ? "&gt; 500" : `${Math.round(x)} bp`
parseMonth = (s) =&gt; new Date(`${s}-01T00:00:00Z`)
// Sharpe, annualised, sample std (ddof = 1): matches the release convention
sharpe = (r) =&gt; {
  const n = r.length, m = r.reduce((a, b) =&gt; a + b, 0) / n
  const v = r.reduce((a, b) =&gt; a + (b - m) ** 2, 0) / (n - 1)
  const vol = Math.sqrt(v) * Math.sqrt(12)
  return vol &gt; 1e-12 ? (m * 12) / vol : NaN
}
netSeries = (r, to, bp) =&gt; r.map((x, i) =&gt; x - to[i] * bp / 1e4)
wealthPath = (r) =&gt; { let w = 1; return r.map((x) =&gt; (w *= 1 + x)) }
nberMarks = (nber) =&gt; Plot.rectX(nber, { x1: (d) =&gt; parseMonth(d.start), x2: (d) =&gt; parseMonth(d.end), fill: palette.band })






















































































试一试。 (1) k = 1（不复制）时，两个主题各占拟合风险的 50%。(2) 把 k（主题 X 的份数）拖到 5：数据一点没变，主题 X 的份额却升到 73%；虚线表示同样复制五份、但把惩罚按份数加回去的对照，始终停在 50%。(3) 把 λ（惩罚强度）调到 4，份额升到约 83%；调到 0.1，则降到约 55%。(4) 把 λ 调回 1，再把 ρ（两个主题的重叠程度）调到 0.9：份额升到约 80%。重叠程度居中时，份额几乎不动（约 72%–73%），所以份额并不随 ρ 持续上升。请留意：副本没有带来任何新信息，变的只是惩罚对主题 X 收取的“价格”。这里 λ 固定不变；论文中 λ 会重新选定，而单单一个重新选定的数值，一般抵消不了只偏向一个主题的复制（第 I.B 节，第 5 页）。示意数字，并非论文数据。



图 1：示意例子，复制一个主题但不增加信息。两个特征，各属一个主题，按设定同样有用。


// Illustrative toy (not the paper's data). Two standardised characteristics, one per theme,
// with correlation rho; true coefficients 0.5 and 0.5; population ridge with penalty lambda.
// Copying the theme-X column k times with an identity penalty on the encoded coefficients
// is the same as penalising the canonical coefficient by lambda * b_x^2 / k (paper eq. 2).
// The transported control multiplies the copies' penalty back so the canonical penalty is unchanged.
viewof jmp_toy_k = Inputs.range([1, 10], { value: 1, step: 1, label: LANG === "zh" ? "主题 X 的份数 k（1 = 不复制）" : "Copies of theme X, k (1 = no copying)" })







viewof jmp_toy_rho = Inputs.range([0, 0.9], { value: 0.5, step: 0.05, label: LANG === "zh" ? "两个主题的重叠程度（相关系数 ρ）" : "Overlap of the two themes (correlation ρ)" })







viewof jmp_toy_lambda = Inputs.range([0.1, 4], { value: 1, step: 0.1, label: LANG === "zh" ? "惩罚强度 λ" : "Penalty strength λ" })







jmp_toy_beta = [0.5, 0.5]
jmp_toy_fit = (k, rho, lam) =&gt; {
  // b = (Sigma + lam * diag(1/k, 1))^{-1} Sigma beta, Sigma = [[1, rho], [rho, 1]]
  const a11 = 1 + lam / k, a12 = rho, a22 = 1 + lam
  const s1 = jmp_toy_beta[0] + rho * jmp_toy_beta[1], s2 = rho * jmp_toy_beta[0] + jmp_toy_beta[1]
  const det = a11 * a22 - a12 * a12
  const bx = (a22 * s1 - a12 * s2) / det, bz = (a11 * s2 - a12 * s1) / det
  const varU = bx * bx + bz * bz + 2 * rho * bx * bz
  const share = (bx * bx + rho * bx * bz) / varU
  const dx = jmp_toy_beta[0] - bx, dz = jmp_toy_beta[1] - bz
  const excess = dx * dx + dz * dz + 2 * rho * dx * dz
  return { bx, bz, share, excess }
}
jmp_toy_rows = Array.from({ length: 10 }, (_, i) =&gt; i + 1).flatMap((k) =&gt; [
  { k, rule: LANG === "zh" ? "每份照常逐列惩罚" : "Ordinary penalty on each copy", share: 100 * jmp_toy_fit(k, jmp_toy_rho, jmp_toy_lambda).share },
  { k, rule: LANG === "zh" ? "换算惩罚（精确对照，虚线）" : "Penalty scaled back up (exact control, dashed)", share: 100 * jmp_toy_fit(1, jmp_toy_rho, jmp_toy_lambda).share }
])
jmp_toy_now = jmp_toy_fit(jmp_toy_k, jmp_toy_rho, jmp_toy_lambda)
jmp_toy_base = jmp_toy_fit(1, jmp_toy_rho, jmp_toy_lambda)





































jmp_toy_chart = Plot.plot({
  width: Math.min(width, 760), height: 280, marginLeft: 56, marginRight: 16, marginBottom: 44, style: { fontFamily: "inherit", fontSize: 12 },
  ariaLabel: LANG === "zh" ? "示意性示例：复制主题 X 时，主题 X 在拟合风险中的份额" : "Illustrative example: theme X's share of fitted risk as theme X is copied",
  ariaDescription: LANG === "zh"
    ? "两条线，横轴为主题 X 的份数 k（1 到 10）。每份照常逐列惩罚时，主题 X 的份额随 k 上升；把惩罚按份数加回去（换算惩罚）时，份额始终停在 50%。"
    : "Two lines against the number of copies from 1 to 10. With an ordinary penalty on each copy, theme X's share rises with k; with the penalty scaled back up, it stays at 50%.",
  x: { label: LANG === "zh" ? "主题 X 的份数 k" : "Copies of theme X (k)", domain: [1, 10], ticks: 10, labelAnchor: "center", labelOffset: 34 },
  y: { label: LANG === "zh" ? "主题 X 在拟合风险中的份额（%）" : "Theme X's share of fitted risk (%)", domain: [0, 100], grid: true },
  color: { domain: jmp_toy_rows.slice(0, 2).map((d) =&gt; d.rule), range: [palette.naipca_iab, palette.rp_pca], legend: true },
  marks: [
    Plot.ruleY([50], { stroke: palette.rule }),
    Plot.line(jmp_toy_rows.filter((d, i) =&gt; i % 2 === 0), { x: "k", y: "share", stroke: "rule", strokeWidth: 2 }),
    Plot.line(jmp_toy_rows.filter((d, i) =&gt; i % 2 === 1), { x: "k", y: "share", stroke: "rule", strokeWidth: 2, strokeDasharray: "5 4" }),
    Plot.dot([{ k: jmp_toy_k, share: 100 * jmp_toy_now.share }], { x: "k", y: "share", r: 6, fill: palette.naipca_iab }),
    Plot.text([{ k: jmp_toy_k, share: 100 * jmp_toy_now.share }], { x: "k", y: "share", text: (d) =&gt; `${d.share.toFixed(0)}%`, dx: 10, dy: -10, textAnchor: "start", fontWeight: 600 })
  ]
})







jmp_toy_readout = html`&lt;div class="table-scroll"&gt;&lt;table class="tbl-num"&gt;
