  x: { label: LANG === "zh" ? "对拟合收益的贡献（示意单位）" : "Contribution to the fitted return (illustrative units)", labelAnchor: width &lt; 500 ? "right" : "center", labelOffset: 40, grid: true },
  y: { label: null, domain: csm_toy_rows.map((d) =&gt; d.ruler).filter((v, i, a) =&gt; a.indexOf(v) === i) },
  color: { domain: csm_toy_parts.map((p) =&gt; p[1]), range: [palette.complete, palette.qz_ipca, palette.ipca], legend: true },
  marks: [
    Plot.barX(csm_toy_rows, Plot.stackX({ x: "value", y: "ruler", fill: "part", order: csm_toy_parts.map((p) =&gt; p[1]) })),
    Plot.ruleX([0], { stroke: palette.muted }),
    Plot.tickX([{ x: csm_toy_I.latent + csm_toy_I.observed + csm_toy_I.intercept }], { x: "x", stroke: "black", strokeWidth: 2, strokeDasharray: "4 2" }),
    Plot.tip(csm_toy_rows, Plot.pointerY(Plot.stackX({ x: "value", y: "ruler", title: (d) =&gt; `${d.ruler}\n${d.part}: ${fmt2(d.value)}` })))
  ]
})







csm_toy_table = {
  const zh = LANG === "zh"
  const r = (s) =&gt; ({ lat: fmt2(s.latent), obs: fmt2(s.observed), int: fmt2(s.intercept), tot: fmt2(s.latent + s.observed + s.intercept), exp: s.exposure.toFixed(3) })
  const I = r(csm_toy_I), G = r(csm_toy_G)
  return html`&lt;div class="table-scroll"&gt;&lt;table class="table table-sm"&gt;&lt;thead&gt;&lt;tr&gt;&lt;th&gt;&lt;/th&gt;&lt;th&gt;${zh ? "潜在因子" : "Hidden factor"}&lt;/th&gt;&lt;th&gt;${zh ? "可观测因子" : "Observed factor"}&lt;/th&gt;&lt;th&gt;${zh ? "截距" : "Intercept"}&lt;/th&gt;&lt;th&gt;${zh ? "拟合收益" : "Fitted return"}&lt;/th&gt;&lt;th&gt;${zh ? "截距承载量（平方）" : "How much the intercept carries (squared size)"}&lt;/th&gt;&lt;/tr&gt;&lt;/thead&gt;
  &lt;tbody&gt;&lt;tr&gt;&lt;td&gt;${zh ? "普通尺子" : "Plain ruler (treats the two signals as unrelated)"}&lt;/td&gt;&lt;td&gt;${I.lat}&lt;/td&gt;&lt;td&gt;${I.obs}&lt;/td&gt;&lt;td&gt;${I.int}&lt;/td&gt;&lt;td&gt;&lt;strong&gt;${I.tot}&lt;/strong&gt;&lt;/td&gt;&lt;td&gt;${I.exp}&lt;/td&gt;&lt;/tr&gt;
  &lt;tr&gt;&lt;td&gt;${zh ? `特征尺子（ρ = ${csm_toy_rho.toFixed(2)}）` : `Characteristic ruler (counts shared stocks; overlap ρ = ${csm_toy_rho.toFixed(2)})`}&lt;/td&gt;&lt;td&gt;${G.lat}&lt;/td&gt;&lt;td&gt;${G.obs}&lt;/td&gt;&lt;td&gt;${G.int}&lt;/td&gt;&lt;td&gt;&lt;strong&gt;${G.tot}&lt;/strong&gt;&lt;/td&gt;&lt;td&gt;${G.exp}&lt;/td&gt;&lt;/tr&gt;&lt;/tbody&gt;&lt;/table&gt;&lt;/div&gt;`
}







怎么读。上方条形用普通尺子拆分一只股票的拟合收益；下方条形用特征尺子，两个信号的重叠度为 ρ。虚线刻度标出拟合收益：无论用哪把尺子，股票 A 都是 1.00，股票 B 都是 0.20。表格最后一列两只股票相同：用各自的尺子衡量截距整体承载多少，即截距上限所限制的量；某只股票的截距部分变大时，它仍可能变小。默认 ρ = 0.40 已经偏高：真实重叠度中位数为 0.06，二十对中仅一对超过 0.38（第 31 页）。来源：按论文命题 1 及式 3.2 至 3.4 的匹配变换计算的示意例子；无数据文件。


这个比方也有不同之处：特征尺子一旦选定，其取值由特征数据计算得出，所以尺子上的刻度，正是用你要量的同一批数据画出来的。
